function correctionNormalizeMetadata(array $proposal):array{$metadata=$proposal["metadata"]??null;$statement=$proposal["statement"]??null;if(!is_array($metadata)||!is_string($statement))throw new RuntimeException("Os metadados da proposta são inválidos.");foreach(["board","exam","position"] as $field){$value=$metadata[$field]??null;if($value!==null&&!is_string($value))throw new RuntimeException("Os metadados da proposta são inválidos.");$metadata[$field]=is_string($value)?(trim($value)?:null):null;}$year=$metadata["year"]??null;if($year!==null&&(!is_int($year)||$year<1900||$year>2100))throw new RuntimeException("Os metadados da proposta são inválidos.");$metadata["year"]=$year;if(preg_match("/^\s*\(\s*([^\/()]{2,80})\s*\/\s*(.+?)\s*[–-]\s*((?:19|20)\d{2})\s*\)\s*/u",$statement,$match)===1){$metadata["board"]??=trim($match[1])?:null;$metadata["exam"]??=trim($match[2])?:null;$metadata["year"]??=(int)$match[3];$statement=trim(mb_substr($statement,mb_strlen($match[0],"UTF-8"),null,"UTF-8"));}$proposal["statement"]=$statement;$proposal["metadata"]=$metadata;return $proposal;}
