function correctionProposalShape(array $proposal):array{$options=$proposal['options']??null;return ['statement_is_string'=>is_string($proposal['statement']??null),'options_is_array'=>is_array($options),'options_count'=>is_array($options)?count($options):null,'figures_count'=>is_array($proposal['figures']??null)?count($proposal['figures']):null,'summary_is_string'=>is_string($proposal['summary']??null)];}
function correctionCompleteOptions(array $original,array $proposal):array{if(($proposal['options']??null)===[])$proposal['options']=array_map(static fn(array $option):array=>['id'=>$option['id'],'label'=>$option['label'],'content'=>$option['content']],$original['options']??[]);return $proposal;}
function correctionNormalizeVisualAsset(array $proposal,array $evidencePages):array{$statement=$proposal["statement"]??null;$figures=$proposal["figures"]??null;if(!is_string($statement)||!is_array($figures))return $proposal;foreach($figures as $index=>$figure){$page=$figure["page"]??null;if(!is_int($page)||!in_array($page,$evidencePages,true))throw new RuntimeException("A proposta indicou uma página visual fora das evidências.");$marker="[[FIGURA:".($index+1)."]]";if(substr_count($statement,$marker)!==1)throw new RuntimeException("Cada figura precisa ter um marcador único no enunciado.");}$withoutMarkers=preg_replace("/\[\[FIGURA:\d+\]\]/","",$statement)??$statement;if(preg_match("/\[\[FIGURA:\d+\]\]/",$withoutMarkers)===1)throw new RuntimeException("O enunciado contém marcador visual inválido.");return $proposal;}
function correctionExtractEmbeddedImage(string $pdf,int $page,string $target,int $position=0):bool{$directory=dirname($target);if(!is_dir($directory)&&!mkdir($directory,0755,true)&&!is_dir($directory))return false;$prefix=$directory."/candidate-".bin2hex(random_bytes(6));exec("pdfimages -f ".$page." -l ".$page." -png ".escapeshellarg($pdf)." ".escapeshellarg($prefix),$ignored,$status);$images=glob($prefix."-*")?:[];$images=array_values(array_filter($images,static fn(string $path):bool=>is_file($path)&&@getimagesize($path)!==false));if($status!==0||!isset($images[$position]))return false;usort($images,static fn(string $a,string $b):int=>(filesize($b)?:0)<=>(filesize($a)?:0));if(!isset($images[$position])||!rename($images[$position],$target))return false;foreach($images as $image)if(is_file($image))unlink($image);return true;}
