 $source=null;$searchedPhrase=correctionRequestedEvidencePhrase($job->instruction);$matchedPages=[];if(is_string($sourceJobId)&&is_array($pages)){$source=$em->find(QuestionPdfImportJobRecord::class,$sourceJobId);if($source instanceof QuestionPdfImportJobRecord&&is_file($source->documentPath)){if($searchedPhrase!==null){$matchedPages=correctionSearchPdfPages($source->documentPath,$searchedPhrase);if($matchedPages!==[])$evidencePages=correctionEvidencePages(array_merge(array_map("intval",$pages),$matchedPages));correctionLog("evidence_search",$job->id,["phrase_sha256"=>hash("sha256",$searchedPhrase),"matched_pages"=>$matchedPages,"evidence_pages"=>$evidencePages]);}foreach($evidencePages as $page){$target=$workspace."/source-page-".$page;exec("pdftoppm -png -f ".$page." -l ".$page." -singlefile ".escapeshellarg($source->documentPath)." ".escapeshellarg($target),$ignored,$status);if($status===0&&is_file($target.".png"))$images[]=$target.".png";}}}
 correctionLog('pdf_rendered',$job->id,['pages'=>count($images),'evidence_pages'=>$evidencePages]);
 $prompt="Use exclusivamente o snapshot abaixo e as imagens anexadas source-page-*.png. Elas incluem as páginas de origem, duas páginas antes/depois e, quando a instrução solicitar procura de trecho, também as páginas localizadas pela busca determinística no PDF. Não tente ler arquivos nem executar ferramentas: todos os dados autorizados estão no snapshot e nos anexos. Determine autonomamente todas as figuras necessárias. Extraia os metadados impressos da questão em metadata: board é a banca, exam é o concurso ou órgão, position é o cargo e year é o ano; use null quando um campo não estiver explicitamente visível. Remova do início do enunciado cabeçalhos de banca, concurso, cargo e ano quando forem metadados, sem remover texto intelectual da questão. Para cada item de figures, informe a página de evidência e insira no enunciado exatamente um marcador sequencial [[FIGURA:1]], [[FIGURA:2]] e assim por diante, no ponto correto, logo após o texto que faz referência a ela. Use figures vazio quando não houver figura. A ordem de figures precisa corresponder à ordem dos marcadores. Não mova conteúdo intelectual. Faça apenas correção estrutural ou de formatação. Preserve significado, gabarito, IDs, rótulos, quantidade e ordem. Não invente conteúdo. Mesmo que nenhuma alternativa mude, options deve conter todas as alternativas originais com seus IDs, rótulos e conteúdos. Devolva somente JSON conforme response-schema.json. <snapshot>" . $promptPayload . "</snapshot>";
